{
  "risks": [
    {
      "condition": "Proposal submission is bound by REQ-0002 to be a single PDF of no more than 20 pages, uploaded via the procurement portal by 2026-12-01 12:00 UTC.",
      "event": "The proposal exceeds 20 pages or portal congestion delays the final PDF upload past the deadline.",
      "effect": "The bid is rejected outright without evaluation, causing total loss of pursuit effort.",
      "assumptions": [
        "The procurement portal will remain accessible without interruption up to the deadline."
      ],
      "owner_role": "Bid manager",
      "trigger": "Draft proposal exceeds 18 pages or upload is not initiated two hours prior to the deadline.",
      "responses": [
        "Enforce a strict 18-page budget across all sections during drafting.",
        "Perform a dry-run test upload of the proposal PDF one working day prior to the deadline."
      ],
      "residual_exposure": "Low on document length once enforced, but external portal downtime remains a residual hazard.",
      "evidence_src_ids": [
        "SRC-0015"
      ]
    },
    {
      "condition": "The service must go live for students by 2027-01-11 per REQ-0014, leaving a very tight deployment window after award.",
      "event": "Integration with the College's student records system via REST API (REQ-0009) encounters undocumented API constraints or delayed credential provisioning.",
      "effect": "The service fails to go live on the first day of spring enrollment, breaching the contract timeline.",
      "assumptions": [
        "The College will provide immediate access to a sandbox REST API environment upon contract award."
      ],
      "owner_role": "Integration lead",
      "trigger": "API documentation is not made available within five days of contract award.",
      "responses": [
        "Request the REST API documentation and sandbox endpoint specifications during the pre-award clarification period.",
        "Build a mock API wrapper to enable parallel frontend and backend integration testing."
      ],
      "residual_exposure": "Dependence on the responsiveness of the College's IT staff to resolve API integration blocks.",
      "evidence_src_ids": [
        "SRC-0027",
        "SRC-0032"
      ]
    },
    {
      "condition": "REQ-0008 states the Supplier should migrate approximately 38,000 signed records held in the current tool by 2027-02-28.",
      "event": "Legacy data formats are inconsistent or export functions from the current tool are constrained, causing migration scripts to fail or corrupt audit metadata.",
      "effect": "Historical records are missing or inaccessible, undermining compliance with the ten-year retention mandate.",
      "assumptions": [
        "The current tool provides a structured export mechanism for all 38,000 records."
      ],
      "owner_role": "Data migration lead",
      "trigger": "Sample data extract from the current tool reveals unmapped fields or missing audit trails.",
      "responses": [
        "Request a sample data extract from the legacy tool prior to finalising the migration schedule.",
        "Develop automated data cleansing and validation scripts early in the delivery phase."
      ],
      "residual_exposure": "Manual intervention required to clean corrupt legacy records if automated scripts fail.",
      "evidence_src_ids": [
        "SRC-0010",
        "SRC-0025",
        "SRC-0026"
      ]
    }
  ],
  "open_questions": [
    {
      "text": "What is the specific technology stack and rate-limiting policy of the College's existing REST API referenced in REQ-0009?",
      "src_ids": [
        "SRC-0027"
      ]
    },
    {
      "text": "In what format are the 38,000 signed records currently stored in the legacy tool for migration under REQ-0008?",
      "src_ids": [
        "SRC-0010",
        "SRC-0026"
      ]
    }
  ]
}
